   title = 'Confira antes do disparo'; body = `<p class="mb-5 text-sm leading-6 text-n-muted">No produto, envie uma cópia de teste para revisar a aparência na sua caixa de entrada.</p><label class="text-xs font-medium text-n-muted">Endereço para o teste<input type="email" aria-label="Endereço para o teste" placeholder="voce@example.com" class="mt-2 h-11 w-full rounded-xl border border-n-line px-3 text-sm focus:border-n-blue focus:outline-none"></label><p class="mt-4 text-xs text-n-muted">Este protótipo não envia e-mails.</p>`; footer = button('Simular teste', 'send', 'simulate-test', 'primary');
